package app.vera.coach.visionbeta;
import android.app.*;import android.content.*;import android.content.pm.ServiceInfo;import android.location.*;import android.os.*;import org.json.*;
/** User-started location FGS. Persists summaries only, never coordinates or bearer tokens. */
public class SportTracker24 extends Service implements LocationListener {
 private static volatile SportTracker24 live; private static final String PREF="vera.sport24",KEY="summary";private static final int ID=2407;
 private JSONObject data=new JSONObject();private SportMath24 gps=new SportMath24();private LocationManager locations;private long resumed=0;private double duration=0,lapTime=0,lapMeters=0;private Handler handler=new Handler(Looper.getMainLooper());
 private final Runnable tick=new Runnable(){public void run(){if("active".equals(data.optString("status"))){if(seconds()>=86400){duration=86400;resumed=0;command("finish");return;}persist();notifyState();handler.postDelayed(this,5000);}}};
 private static JSONObject stored(Context c){try{return new JSONObject(c.getSharedPreferences(PREF,0).getString(KEY,"{}"));}catch(Exception e){return new JSONObject();}}
 private static boolean owns(JSONObject d,String owner){return owner!=null&&owner.equals(d.optString("owner"));}
 public static synchronized String snapshot(Context c,String owner){SportTracker24 current=live;JSONObject d=current!=null?current.summary():stored(c);if(!d.has("id"))return "{}";if(!owns(d,owner))return "{\"otherAccount\":true}";try{d.remove("owner");if(current==null&&"active".equals(d.optString("status"))){d.put("status","paused");d.put("interrupted",true);}}catch(Exception ignored){}return d.toString();}
 public static synchronized void discard(Context c,String owner,String id){SportTracker24 current=live;JSONObject d=current!=null?current.summary():stored(c);if(!owns(d,owner)||!id.equals(d.optString("id")))return;if(current!=null){synchronized(current){current.data=new JSONObject();current.stopCapture();}}c.getSharedPreferences(PREF,0).edit().remove(KEY).apply();}
 public static synchronized void pauseForLogout(){SportTracker24 current=live;if(current!=null)current.command("pause");}
 public static void launch(Context c,String owner,String action,String sport){Intent i=new Intent(c,SportTracker24.class).putExtra("owner",owner).putExtra("action",action).putExtra("sport",sport);if("start".equals(action)||"resume".equals(action))c.startForegroundService(i);else if(live!=null)c.startService(i);else {JSONObject d=stored(c);if(owns(d,owner)&&"finish".equals(action))try{d.put("status","finished");d.put("end",System.currentTimeMillis());c.getSharedPreferences(PREF,0).edit().putString(KEY,d.toString()).apply();}catch(Exception ignored){}}}
 public void onCreate(){super.onCreate();locations=(LocationManager)getSystemService(LOCATION_SERVICE);data=stored(this);duration=data.optDouble("durationSeconds",0);gps.meters=data.optDouble("distanceMeters",0);JSONArray laps=data.optJSONArray("laps");if(laps!=null)for(int i=0;i<laps.length();i++){lapTime+=laps.optJSONObject(i).optDouble("durationSeconds");lapMeters+=laps.optJSONObject(i).optDouble("distanceMeters");}try{if("active".equals(data.optString("status")))data.put("status","paused");}catch(Exception ignored){}((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).createNotificationChannel(new NotificationChannel("sport24","Actividad deportiva en curso",NotificationManager.IMPORTANCE_LOW));live=this;}
 public synchronized int onStartCommand(Intent i,int flags,int startId){if(i==null){stopSelf();return START_NOT_STICKY;}String owner=i.getStringExtra("owner"),action=i.getStringExtra("action"),sport=i.getStringExtra("sport");if(owner==null||owner.length()>400){stopSelf();return START_NOT_STICKY;}try{
  if("start".equals(action)&&!data.has("id")){if(!"cycling".equals(sport)&&!"running".equals(sport)&&!"walking".equals(sport)){stopSelf();return START_NOT_STICKY;}data.put("id","gps-"+java.util.UUID.randomUUID());data.put("owner",owner);data.put("sport",sport);data.put("start",System.currentTimeMillis());data.put("laps",new JSONArray());data.put("status","paused");}
  if(!owns(data,owner)){stopSelf();return START_NOT_STICKY;}
  if("start".equals(action)||"resume".equals(action)){if(Build.VERSION.SDK_INT>=29)startForeground(ID,notification(),ServiceInfo.FOREGROUND_SERVICE_TYPE_LOCATION);else startForeground(ID,notification());if(!"finished".equals(data.optString("status")))command("resume");else stopCapture();}
  else command(action);
 }catch(Exception e){try{data.put("error","No se pudo iniciar el GPS. Revisa el permiso de ubicación precisa y activa la ubicación.");data.put("status","paused");}catch(Exception ignored){}persist();stopCapture();}return START_NOT_STICKY;}
 private synchronized double seconds(){return duration+(resumed>0?(SystemClock.elapsedRealtime()-resumed)/1000.0:0);}
 private synchronized JSONObject summary(){try{JSONObject out=new JSONObject(data.toString());out.put("durationSeconds",Math.round(seconds()));out.put("distanceMeters",Math.round(gps.meters));out.put("avgSpeedKmh",seconds()>0?gps.meters/seconds()*3.6:0);return out;}catch(Exception e){return new JSONObject();}}
 private synchronized void persist(){getSharedPreferences(PREF,0).edit().putString(KEY,summary().toString()).apply();}
 private synchronized void command(String action){try{
  if("resume".equals(action)&&!"active".equals(data.optString("status"))&&!"finished".equals(data.optString("status"))){if(!locations.isProviderEnabled(LocationManager.GPS_PROVIDER))throw new IllegalStateException();data.remove("error");gps.resetAnchor();resumed=SystemClock.elapsedRealtime();data.put("status","active");locations.requestLocationUpdates(LocationManager.GPS_PROVIDER,2000,0,this,Looper.getMainLooper());handler.removeCallbacks(tick);handler.post(tick);}
  else if("pause".equals(action)||"finish".equals(action)){duration=Math.min(86400,seconds());resumed=0;locations.removeUpdates(this);gps.resetAnchor();data.put("status","finish".equals(action)?"finished":"paused");if("finish".equals(action)){data.put("end",System.currentTimeMillis());if(duration-lapTime>=1&&data.getJSONArray("laps").length()<200){data.getJSONArray("laps").put(new JSONObject().put("durationSeconds",duration-lapTime).put("distanceMeters",gps.meters-lapMeters));lapTime=duration;lapMeters=gps.meters;}}handler.removeCallbacks(tick);persist();if("finish".equals(action)){stopCapture();return;}}
  else if("lap".equals(action)&&"active".equals(data.optString("status"))&&data.getJSONArray("laps").length()<200){double seconds=seconds();if(seconds-lapTime<1)return;data.getJSONArray("laps").put(new JSONObject().put("durationSeconds",seconds-lapTime).put("distanceMeters",gps.meters-lapMeters));lapTime=seconds;lapMeters=gps.meters;}
  persist();notifyState();
 }catch(Exception e){duration=Math.min(86400,seconds());resumed=0;try{locations.removeUpdates(this);data.put("status","paused");data.put("error","GPS no disponible. La sesión está pausada; revisa ubicación y permisos.");}catch(Exception ignored){}persist();stopCapture();}}
 public synchronized void onLocationChanged(Location l){if(!"active".equals(data.optString("status")))return;long now=SystemClock.elapsedRealtime();if(gps.add(l.getLatitude(),l.getLongitude(),l.hasAccuracy()?l.getAccuracy():999,l.getElapsedRealtimeNanos()/1000000,now,data.optString("sport"))){try{data.put("lastFix",System.currentTimeMillis());data.put("accuracyMeters",Math.round(l.getAccuracy()));}catch(Exception ignored){}persist();}}
 public synchronized void onProviderDisabled(String provider){command("pause");try{data.put("error","Se ha desactivado la ubicación. Sesión pausada.");}catch(Exception ignored){}persist();}public void onProviderEnabled(String p){}public void onStatusChanged(String p,int s,Bundle b){}
 private Notification notification(){Intent open=new Intent(this,Main.class).addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP);PendingIntent pi=PendingIntent.getActivity(this,0,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);String text="active".equals(data.optString("status"))?"GPS activo · "+Math.round(gps.meters)+" m · "+(int)(seconds()/60)+" min":"Actividad pausada · abre Vera para continuar";return new Notification.Builder(this,"sport24").setSmallIcon(android.R.drawable.ic_menu_mylocation).setContentTitle("Vera · actividad deportiva").setContentText(text).setContentIntent(pi).setOngoing(true).setOnlyAlertOnce(true).setVisibility(Notification.VISIBILITY_PRIVATE).build();}
 private void notifyState(){((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(ID,notification());}
 private void stopCapture(){handler.removeCallbacks(tick);if(locations!=null)try{locations.removeUpdates(this);}catch(SecurityException ignored){}stopForeground(true);stopSelf();}
 public synchronized void onDestroy(){duration=Math.min(86400,seconds());resumed=0;try{if("active".equals(data.optString("status")))data.put("status","paused");}catch(Exception ignored){}handler.removeCallbacks(tick);if(locations!=null)try{locations.removeUpdates(this);}catch(SecurityException ignored){}if(data.has("id"))persist();live=null;super.onDestroy();}
 public IBinder onBind(Intent i){return null;}
}
